local CommonAestheticsNode = Class('CommonAestheticsNode')
local DOTween = CS.DG.Tweening.DOTween
function CommonAestheticsNode:__init()
    self.callBack = nil
end

function CommonAestheticsNode:__delete()
    self.callBack = nil
end

function CommonAestheticsNode:Awake()
    SetButtonAction(self.BtnExplain.gameObject,Bind(self,self.OnBtnExplainClick))
end

function CommonAestheticsNode:RefreshShow(num,isHaveBtn,callBack,isPlayAni,curNum)
    if not isNull(num) then
        if isPlayAni then
            CfUtils.FillText(self.TextNumber,curNum)
            DOTween.To(function(value)
                CfUtils.FillText(self.TextNumber,math.floor(value))
            end, curNum, num, 1)
        else
            CfUtils.FillText(self.TextNumber,num)
        end
    end

    CfUtils.SetActive(self.BtnExplain.gameObject,isHaveBtn)

    if not isNull(callBack) then
       self.callBack = callBack
    end
    KTool.SetActive(self.controller.gameObject,true)
end

function CommonAestheticsNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

function CommonAestheticsNode:OnBtnExplainClick()
    if not isNull(self.callBack) then
        self.callBack()
    end
end

return CommonAestheticsNode